import json
import sys


def _apply_tx(ops, state):
    """Return the state after executing ops, or None if some observation fails."""
    d = dict(state)
    for op in ops:
        kind = op[0]
        if kind == "get":
            if d.get(op[1]) != op[2]:
                return None
        elif kind == "put":
            d[op[1]] = op[2]
        elif kind == "del":
            d.pop(op[1], None)
        elif kind == "cas":
            _, key, old, new, want = op
            cur = d.get(key)
            ok = (cur == old)
            if ok != want:
                return None
            if ok:
                if new is None:
                    d.pop(key, None)
                else:
                    d[key] = new
        else:  # scan
            _, low, high, pairs = op
            got = [[k, d[k]] for k in sorted(d) if low <= k < high]
            if got != pairs:
                return None
    return d


