"""Linearizability checker for atomic range transactions.

A whole transaction is one atomic operation.  For a completed concurrent
history we must either return a serial order of the transactions that
reproduces every observed result (starting from ``initial`` and ending at
``final``), or prove that no such order exists.

The search runs backwards from the final state.  Because every operation of a
transaction only ever touches one key (scans compare a per-key expectation)
and the effects on different keys are independent, the set of states from
which a suffix of transactions can validly run down to ``final`` is always a
product of per-key allowed-value sets.  Prepending a transaction to a suffix
therefore transforms each per-key set independently, which makes the backward
search very compact.  A forward DFS is kept as a fallback.
"""

import json
import sys


# ---------------------------------------------------------------------------
# value encoding: None (absent) -> 0, integer v in [-9, 9] -> v + 10
# ---------------------------------------------------------------------------

def _code(v):
    return 0 if v is None else v + 10


def _scan_is_satisfiable(op, keys):
    """A scan observation that cannot match any state kills the history."""
    lo, hi, pairs = op[1], op[2], op[3]
    prev = None
    for pr in pairs:
        if not isinstance(pr, list) or len(pr) != 2:
            return False
        k, v = pr
        if (not isinstance(k, str) or k not in keys or not (lo <= k < hi)
                or type(v) is not int or not (-9 <= v <= 9)):
            return False
        if prev is not None and k <= prev:
            return False
        prev = k
    return True


